// --- Feature Badge ---
// Feature Badge Toggle Functionality
// ==================================================
document.addEventListener('DOMContentLoaded', function () {
    const enableThinkBtn = document.getElementById('enebleThink');
    const toggleGraphBtn = document.getElementById('toggleGraphBtn');
    const toggleCanvasBtn = document.getElementById('toggleCanvasBtn');
    const featurePlaceholder = document.getElementById('selected-feature-placeholder');

    let activeFeature = null;

    const features = {
        deepthink: {
            id: 'deepthink',
            name: 'DeepThink',
            icon: 'fas fa-flask',
            btn: enableThinkBtn
        },
        graph: {
            id: 'graph',
            name: 'Graph',
            icon: 'fas fa-chart-line',
            btn: toggleGraphBtn
        },
        canvas: {
            id: 'canvas',
            name: 'Canvas',
            icon: 'fa-solid fa-pen-to-square',
            btn: toggleCanvasBtn
        }
    };

    function createFeatureBadge(feature) {
        const badge = document.createElement('button');
        badge.className = 'feature-badge';
        badge.type = 'button';
        badge.innerHTML = `<i class="${feature.icon}"></i><span class="feature-badge-text">${feature.name}</span>`;
        badge.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            disableFeature();
        };
        return badge;
    }

    function enableFeature(featureKey, options = {}) {
        // If the same feature is clicked, disable it (unless explicitly keeping it active)
        if (activeFeature === featureKey) {
            if (options && options.keepActive) return;
            disableFeature();
            return;
        }

        // Disable previous feature if any
        if (activeFeature) {
            disableFeature();
        }

        // Enable new feature
        activeFeature = featureKey;
        const feature = features[featureKey];
        const hasUi = !!(feature && featurePlaceholder && feature.btn);
        if (hasUi) {
            featurePlaceholder.innerHTML = '';
            featurePlaceholder.appendChild(createFeatureBadge(feature));

            // Add visual indication to button
            feature.btn.style.backgroundColor = 'rgba(229, 57, 53, 0.1)';
            feature.btn.style.color = 'var(--primary-red)';
        }

        if (featureKey === 'canvas') {
            if (typeof updateCanvasAvailability === 'function') updateCanvasAvailability();
            const canOpen = Number(getConversationIdFromURL() || 0);
            if (!canOpen) return;
            try { if (typeof closeGraphSidebar === 'function') closeGraphSidebar({ skipFeature: true }); } catch (_) { }
            if (!options.suppressCanvasOpen) {
                try { if (!isCanvasOpen()) openCanvas({ fullscreen: false }); } catch (_) { }
            }
        }
        if (featureKey === 'graph') {
            try { if (isCanvasOpen()) closeCanvas(); } catch (_) { }
            if (!options.suppressGraphOpen) {
                try { if (typeof openGraphSidebar === 'function') openGraphSidebar({ skipFeature: true }); } catch (_) { }
            }
        }
    }

    function disableFeature() {
        if (!activeFeature) return;

        const key = activeFeature;
        const feature = features[key];
        if (feature?.btn) {
            feature.btn.style.backgroundColor = '';
            feature.btn.style.color = '';
        }

        if (featurePlaceholder) featurePlaceholder.innerHTML = '';
        activeFeature = null;

        if (key === 'canvas') {
            try { if (isCanvasOpen()) closeCanvas(); } catch (_) { }
        }
        if (key === 'graph') {
            try { if (typeof closeGraphSidebar === 'function') closeGraphSidebar({ skipFeature: true }); } catch (_) { }
        }
    }

    // Add click listeners to feature buttons
    enableThinkBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        enableFeature('deepthink');
    });

    toggleGraphBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        enableFeature('graph');
    });

    toggleCanvasBtn?.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        enableFeature('canvas');
    });

    // If canvas is opened/closed from elsewhere, keep the badge in sync.
    document.addEventListener('canvas_opened', () => {
        if (activeFeature !== 'canvas') enableFeature('canvas', { suppressCanvasOpen: true });
    });
    document.addEventListener('canvas_closed', () => {
        if (activeFeature === 'canvas') disableFeature();
    });

    window.setActiveFeature = (key, options = {}) => enableFeature(key, options);
    window.resetActiveFeature = (key) => {
        if (key && activeFeature !== key) return;
        disableFeature();
    };
});

const DEFAULT_PAGE_TITLE = 'Apilageai | Playground';

function setPageTitle(title) {
    const clean = String(title || '').trim();
    document.title = clean ? `${clean} | Apilageai` : DEFAULT_PAGE_TITLE;
}

function getConversationTitleById(id) {
    const cid = Number(id || 0);
    if (!cid) return '';
    const list = Array.isArray(lastConversationsList) ? lastConversationsList : [];
    const match = list.find((c) => Number(c?.conversation_id) === cid);
    return String(match?.title || '').trim();
}

