// --- Chat Input Layout ---
// ChatGPT-Style Input Positioning
// ================================================
function updateChatInputPosition() {
    const chatAreaWrapper = document.querySelector('.chat-area-wrapper');
    const messagesContainer = document.getElementById('messages-container');
    const chatStartContainer = document.querySelector('.chat-start-container');

    if (!chatAreaWrapper) return;

    // Check if there are actual messages or if we're viewing an empty chat
    const hasMessages = messagesContainer && messagesContainer.children.length > 0;
    const showingStartContainer = chatStartContainer && chatStartContainer.offsetParent !== null;

    // Empty state = either showing greeting or no messages
    const isEmptyState = showingStartContainer || !messagesContainer;

    if (isEmptyState) {
        chatAreaWrapper.classList.add('empty-state');
        chatAreaWrapper.classList.remove('has-messages');
    } else if (hasMessages) {
        chatAreaWrapper.classList.remove('empty-state');
        chatAreaWrapper.classList.add('has-messages');
    }
}


function updateCanvasAvailability() {
    const toggleCanvasBtn = document.getElementById('toggleCanvasBtn');
    if (!toggleCanvasBtn) return;
    const cid = Number(getConversationIdFromURL() || 0);
    const messagesContainer = document.getElementById('messages-container');
    const chatStartContainer = document.querySelector('.chat-start-container');
    const hasMessages = messagesContainer && messagesContainer.children.length > 0;
    const showingStartContainer = chatStartContainer && chatStartContainer.offsetParent !== null;
    const isEmptyChat = showingStartContainer || !messagesContainer || !hasMessages;
    const canOpen = !!cid && !isEmptyChat;
    toggleCanvasBtn.disabled = !canOpen;
    toggleCanvasBtn.setAttribute('aria-disabled', canOpen ? 'false' : 'true');
    toggleCanvasBtn.title = canOpen ? 'Canvas' : (cid ? 'Send a message to enable canvas' : 'Start a chat to open canvas');
    toggleCanvasBtn.classList.toggle('is-disabled', !canOpen);
}

function resetCanvasForNewChat() {
    try {
        canvasStrokes = [];
        canvasTexts = [];
        canvasPendingStrokes = [];
        canvasPendingTexts = [];
        canvasDocHtml = '';
        canvasPendingDocHtml = null;
        excalidrawCurrentConversationId = null;
        excalidrawPendingScene = null;
        excalidrawScene = { elements: [], appState: {}, files: {} };
        excalidrawSceneHash = '';
        excalidrawLastSavedHash = '';
        excalidrawSaveTimer = null;
        excalidrawSnapshotDataUrl = null;
        excalidrawSnapshotDirty = false;
        excalidrawSnapshotPromise = null;
        excalidrawSnapshotTimer = null;
        if (excalidrawApi && typeof excalidrawApi.updateScene === 'function') {
            excalidrawApplyingRemote = true;
            try {
                excalidrawApi.updateScene({ elements: [], appState: {}, files: {} });
            } catch (_) { }
            excalidrawApplyingRemote = false;
        }
        localStorage.removeItem('canvas_doc_content');
        localStorage.removeItem('canvas_page_size');
        localStorage.removeItem('canvas_show_ruler');
        if (window.canvasEditor && typeof window.canvasEditor.createInitialPage === 'function') {
            window.canvasEditor.createInitialPage();
        }
    } catch (_) { }
}

// Initialize position on load
document.addEventListener('DOMContentLoaded', () => {
    updateChatInputPosition();
    updateCanvasAvailability();
    setPageTitle('');
    if (typeof window.resetActiveFeature === 'function') window.resetActiveFeature();

    // Watch for changes in messages
    const messagesContainer = document.getElementById('messages-container');
    if (messagesContainer) {
        const observer = new MutationObserver(() => {
            updateChatInputPosition();
        });
        observer.observe(messagesContainer, { childList: true, subtree: true });
    }

    // Also watch for chat-start-container visibility changes
    const chatStartContainer = document.querySelector('.chat-start-container');
    if (chatStartContainer) {
        const startObserver = new MutationObserver(() => {
            updateChatInputPosition();
        });
        startObserver.observe(chatStartContainer, { attributes: true, style: true });
    }
});

// Also update when page becomes visible
document.addEventListener('visibilitychange', () => {
    if (!document.hidden) {
        updateChatInputPosition();
        updateCanvasAvailability();
    }
});

// Fallback handler in case the primary graph toggle listener was not attached.
document.addEventListener('click', (e) => {
    const btn = e.target && e.target.closest ? e.target.closest('#toggleGraphBtn') : null;
    if (!btn) return;
    if (typeof window.setActiveFeature === 'function') {
        try {
            window.setActiveFeature('graph');
            return;
        } catch (_) { }
    }
    if (typeof window.openGraphSidebar === 'function') {
        window.openGraphSidebar();
        return;
    }
    const rightSidebar = document.getElementById('rightSidebar');
    const appContainer = document.querySelector('.app-container');
    if (rightSidebar) rightSidebar.classList.add('active');
    if (appContainer) appContainer.classList.add('right-sidebar-active');
});

// ===============================

// --- Trial / Attachments UI ---
// Trial Ended Banner Event Listener
// ===============================
document.addEventListener('DOMContentLoaded', () => {
    const bannerUpgradeBtn = document.getElementById('banner-upgrade-btn');
    const bannerCloseBtn = document.getElementById('banner-close-btn');
    if (bannerUpgradeBtn) {
        bannerUpgradeBtn.addEventListener('click', () => {
            // Open the preference box with billing tab
            openPreferenceBoxWithBillingTab();
        });
    }

    if (bannerCloseBtn) {
        bannerCloseBtn.addEventListener('click', () => {
            // Hide the banner when close button is clicked
            const banner = document.getElementById('trial-ended-banner');
            if (banner) {
                banner.style.display = 'none';
            }
        });
    }
});

// Function to show trial banner if trial has ended AND balance is 0
function showTrialBannerIfEnded() {
    const trialBanner = document.getElementById('trial-ended-banner');
    if (IS_GUEST) {
        if (trialBanner) trialBanner.style.display = 'none';
        return;
    }
    if (trialBanner && window.trialRemaining && window.userBalance !== undefined) {
        // Show banner only if balance is 0 AND any trial remaining value is 0
        const hasNoBalance = window.userBalance <= 0;
        const trialEnded = window.trialRemaining.messages <= 0 || window.trialRemaining.image_uploads <= 0 || window.trialRemaining.image_generations <= 0;
        if (hasNoBalance && trialEnded) {
            trialBanner.style.display = 'block';
        } else {
            trialBanner.style.display = 'none';
        }
    }
}

// Function to manage file attach button state based on trial_remaining.image_uploads AND balance
function updateFileAttachButtonState() {
    const fileAttachBtn = document.getElementById('fileAttach');
    if (fileAttachBtn && window.trialRemaining && window.userBalance !== undefined) {
        // Disable only if balance is 0 AND image uploads trial has ended
        const hasNoBalance = window.userBalance <= 0;
        const imageUploadsEnded = window.trialRemaining.image_uploads <= 0;
        const shouldDisable = hasNoBalance && imageUploadsEnded;
        window.imageUploadsDisabled = !!shouldDisable;

        if (shouldDisable) {
            fileAttachBtn.disabled = true;
            fileAttachBtn.setAttribute('data-tooltip', 'Upgrade to Pro to upload images');
            fileAttachBtn.title = 'Upgrade to Pro to upload images';
        } else {
            fileAttachBtn.disabled = false;
            fileAttachBtn.removeAttribute('data-tooltip');
            fileAttachBtn.title = 'Attach image';
        }
    }
}
